// Habit Tracker - Check daily completion and update streaks
const habits = $input.all().map(item => item.json);
const today = new Date().toISOString().split('T')[0];
const yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];

const results = habits.map(habit => {
  const lastCompleted = habit.last_completed || '';
  const currentStreak = parseInt(habit.streak) || 0;
  const isCompletedToday = lastCompleted === today;
  const wasCompletedYesterday = lastCompleted === yesterday;

  let newStreak = currentStreak;
  let status = 'pending';
  let message = '';

  if (isCompletedToday) {
    // Already completed today
    status = 'completed';
    message = `✅ ${habit.habit}: Đã hoàn thành hôm nay! (Streak: ${currentStreak} ngày)`;
  } else if (wasCompletedYesterday) {
    // Completed yesterday, streak is at risk
    status = 'at_risk';
    message = `⚠️ ${habit.habit}: Hôm qua đã làm, hôm nay chưa làm! (Streak hiện tại: ${currentStreak} ngày)`;
  } else if (lastCompleted && lastCompleted !== today) {
    // Streak broken
    newStreak = 0;
    status = 'broken';
    message = `❌ ${habit.habit}: Streak bị đứt! (Streak cũ: ${currentStreak} ngày). Hãy bắt đầu lại!`;
  } else {
    // Never started
    status = 'not_started';
    message = `📝 ${habit.habit}: Chưa bắt đầu. Mục tiêu: ${habit.target || 'Daily'}`;
  }

  return {
    habit: habit.habit,
    target: habit.target || 'Daily',
    status,
    streak: newStreak,
    last_completed: lastCompleted,
    message
  };
});

const summary = {
  completed: results.filter(r => r.status === 'completed').length,
  at_risk: results.filter(r => r.status === 'at_risk').length,
  broken: results.filter(r => r.status === 'broken').length,
  not_started: results.filter(r => r.status === 'not_started').length
};

console.log(`Habit Check: ${summary.completed}/${results.length} completed today`);

return [{ json: { habits: results, summary, date: today } }];

// Format evening report message
const report = $input.first().json;

const habitMessages = report.habits.map(h => h.message).join('\n');

const motivationalMessages = [
  "💪 Không sao, ngày mới sẽ tốt hơn!",
  "🌟 Mỗi ngày là một cơ hội mới!",
  "🎯 Hãy tập trung vào progress, không phải perfection!",
  "✨ Bạn đang làm tốt lắm! Continue!",
  "🔥 Streak không quan trọng bằng consistency!"
];

const randomMotivation = motivationalMessages[Math.floor(Math.random() * motivationalMessages.length)];

let urgencyLevel = 'low';
if (report.summary.broken > 0) urgencyLevel = 'high';
else if (report.summary.at_risk > 0) urgencyLevel = 'medium';

const message = `📊 Habit Tracker - ${report.date}

━━━━━━━━━━━━━━━━━━━━
${habitMessages}
━━━━━━━━━━━━━━━━━━━━

📈 Summary:
✅ Completed: ${report.summary.completed}
⚠️ At Risk: ${report.summary.at_risk}
❌ Broken: ${report.summary.broken}
📝 Not Started: ${report.summary.not_started}

${urgencyLevel !== 'low' ? randomMotivation : '🎉 Tuyệt vời! Giữ vững phong độ!'}`;

return [{
  json: {
    message,
    urgency: urgencyLevel,
    summary: report.summary,
    date: report.date
  }
}];
